import React from 'react';

// Components
import SEO from './../common/SEO';

// Styles
import './../../assets/css/docpage.css';

// One playable figure. Served from /demos/crossings/<name>/index.html (explicit file:
// a trailing slash falls through to the SPA and returns the shell). The demos are
// generated by scripts/crossings/build.mjs from a port of the UGens, which
// scripts/crossings/test.mjs compares with scsynth.
function Demo({ name, num, title, children }) {
  return (
    <figure>
      <iframe src={`/demos/crossings/${name}/index.html?compact=1`} loading="lazy"
              title={`${title}, interactive`} />
      <figcaption>
        <span className="doc-fignum">Fig. {num}</span>
        <b>{title}.</b> {children}{' '}
        <a href={`/demos/crossings/${name}/index.html`}>Open full size</a>
      </figcaption>
    </figure>
  );
}

function Crossings() {
  return <div className="docpage">
      <SEO
        title="Crossings - Bjarni Gunnarsson"
        description="Crossings: SuperCollider UGens that synthesize wavesets, with seven of them playable in the browser."
        path="/works/docs/crossings"
        noindex={true}
      />
      <h1 className="doc-title">Crossings</h1>
      <p className="doc-standfirst">
        A waveset is the span of a signal between alternate zero crossings. Trevor Wishart used it to cut recorded
        sound at points the sound itself supplies. Crossings turns this around and synthesizes the wavesets.
      </p>

      <h2 id="waveset"><span className="doc-num">1</span>The waveset</h2>

      <p>
        The figures run a JavaScript port of the UGens, the same code for the sound and for the drawings. The upper
        panel of each is the output, with a dashed line at the start of every waveset.
      </p>

      <Demo name="wavesets" num="1" title="One waveset at a time">
        Two half-cycles with their own shape and their own share of the length. A skewed waveset has a DC offset,
        and <i>balance</i> removes it by scaling down the larger half.
      </Demo>

      <h2 id="maps"><span className="doc-num">2</span>Iterated maps</h2>

      <p>
        Each waveset is computed from the one before. A state steps once per waveset through a nonlinear map and
        sets the next length, so the map's orbit becomes the stream of wavesets.
      </p>

      <Demo name="map" num="2" title="An orbit as wavesets">
        Six maps and their bifurcation diagrams. A fixed point gives a single pitch, a periodic orbit a repeating
        pattern of lengths, and chaos a rough stream. Two of the presets are the examples WsMap 5 and WsMap 13.
      </Demo>

      <Demo name="steer" num="3" title="A map steering a map">
        A slower orbit chooses the parameter of the faster one and holds each value for a number of wavesets. The
        lower panel shows the fast orbit settling, or failing to, under each value.
      </Demo>

      <h2 id="walks"><span className="doc-num">3</span>Walks and groups</h2>

      <Demo name="gendy" num="4" title="Stochastic half-cycles">
        Xenakis' dynamic stochastic synthesis with the zero crossings kept: each half-cycle is a curve through
        breakpoints that random-walk once per waveset.
      </Demo>

      <Demo name="group" num="5" title="Groups of half-cycles">
        Any number of half-cycles in place of two. Odd counts put two equal signs side by side, which the spectrum
        shows as subharmonics.
      </Demo>

      <h2 id="recursion"><span className="doc-num">4</span>Recursion and listening</h2>

      <Demo name="nest" num="6" title="Wavesets made of wavesets">
        The same rule divides time at every level of a tree. Where a parent changes sign, a zero crossing of its
        children disappears, so which crossings exist depends on the level they are seen from.
      </Demo>

      <Demo name="hear" num="7" title="A map that hears itself">
        The output returns through a filter or a delay, and each waveset heard is mixed back into the orbit. What
        the loop does to the zero crossings decides what happens to the map.
      </Demo>

      <h2 id="references"><span className="doc-num">5</span>References</h2>

      <ul className="doc-refs">
        <li>
          <a href="https://github.com/bjarnig/Crossings" target="_blank" rel="noopener noreferrer">Crossings</a>
          <span>The SuperCollider UGens, with help files and examples.</span>
          <a className="doc-ref-url" href="https://github.com/bjarnig/Crossings" target="_blank" rel="noopener noreferrer">github.com/bjarnig/Crossings</a>
        </li>
        <li>
          <span className="doc-ref-name">Wishart, 1994</span>
          <span>Audible Design. Orpheus the Pantomime. The waveset and its transformations.</span>
        </li>
        <li>
          <span className="doc-ref-name">Xenakis, 1992</span>
          <span>Formalized Music, revised edition. Pendragon Press. Dynamic stochastic synthesis.</span>
        </li>
      </ul>

    </div>;
}

export default Crossings;
